  assert forall i :: 0 <= i < k3 ==> a[i] >= 8;
  assert forall i :: k3 <= i < |a| ==> a[i] < 8;

  var k4 := SearchRecursive(a, 10);
  assert 0 <= k4 <= |a|;
  assert forall i :: 0 <= i < k4 ==> a[i] >= 10;
  assert forall i :: k4 <= i < |a| ==> a[i] < 10;
}
